use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance};

// NOTE: this node's authority is exactly its `with` clause: Notifier<'digest'>.
// The requested `aap:caps/http-client` import and the enrichment fetch are
// deliberately NOT included: the graph definition does not grant that
// interface yet, so importing it would exceed the node's declared authority
// and would send digest content to a host the node may not reach. Add it
// once the graph's `with` clause actually carries HTTPClient.

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must-read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn render(d: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest for ");
    out.push_str(&d.date);
    out.push('\n');

    let overview = d.overview.trim();
    if !overview.is_empty() {
        out.push('\n');
        out.push_str(overview);
        out.push('\n');
    }

    if d.entries.is_empty() {
        out.push_str("\nNo items made the digest today.\n");
    } else {
        for (n, e) in d.entries.iter().enumerate() {
            out.push('\n');
            out.push_str(&(n + 1).to_string());
            out.push_str(". [");
            out.push_str(importance_label(e.importance));
            out.push_str(" / ");
            out.push_str(category_label(e.category));
            out.push_str("] ");
            out.push_str(e.title.trim());
            out.push('\n');

            let summary = e.summary.trim();
            if !summary.is_empty() {
                out.push_str("   ");
                out.push_str(summary);
                out.push('\n');
            }

            let link = e.link.trim();
            if !link.is_empty() {
                out.push_str("   ");
                out.push_str(link);
                out.push('\n');
            }
        }
    }

    out.push('\n');
    out.push_str(&d.considered.len().to_string());
    out.push_str(" item(s) considered, ");
    out.push_str(&d.entries.len().to_string());
    out.push_str(" included.\n");
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

I left out the `aap:caps/http-client@0.1.0` import and the enrichment fetch. The node's `with` clause grants only `Notifier<'digest'>`, and the graph definition has not been updated yet. Importing it now would exceed the node's declared authority and send digest content to a host it isn't permitted to reach. Once the graph carries the grant, adding the import and the fetch is a small change.

